"""Write vercel-app/api/_tapegraph.py from make_tape_workflow.py, so the page
and the deployment always submit the same graph. Run after editing the scenes.
"""
import json, os
import make_tape_workflow as m

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "vercel-app", "api", "_tapegraph.py")

body = [
    '"""Generated by build/sync_tape_graph.py -- do not edit by hand."""',
    "import json",
    "",
    "SOLO = json.loads(r\'\'\'" + json.dumps(m.graph(couple=False), indent=1) + "\'\'\')",
    "",
    "COUPLE = json.loads(r\'\'\'" + json.dumps(m.graph(couple=True), indent=1) + "\'\'\')",
    "",
    "STAMPS = " + repr(m.stamps()),
    "",
    "SCENE_TITLES = " + repr([s[0] for s in m.SCENES]),
    "",
]
with open(OUT, "w") as f:
    f.write("\n".join(body))
print("wrote", os.path.relpath(OUT, HERE), len(m.SCENES), "scenes")
